SELECT MAX((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE=EDI.BUYER)) AS COM_NAME_LOC, 'VMI' AS GUBUN, MAX((SELECT USER_NAME_LOC||'('||PHONE_NUMBER||')' FROM ICOMLUSR WHERE USER_ID = EDI.POK_USER_ID)) AS USER_NAME_LOC, VPO_NO AS PO_NO, MAX(VPO_DATE) AS VPO_DATE, MAX(RD_DATE) AS RD_DATE, MAX((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = EDI.AGENT)) AS AGENT_NAME, MAX((SELECT TEL_NO FROM ICOMCMPY WHERE COM_CODE = EDI.AGENT)) AS AGENT_TEL_NO, BUYER FROM EDIVPODT EDI WHERE VPO_NO = #{PO_NO} AND BUYER = #{ware_house_code} GROUP BY BUYER,VPO_NO
SELECT MAX((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = POHD.BUYER)) AS COM_NAME_LOC, --00 MAX('재고') AS GUBUN, --01 MAX((SELECT USER_NAME_LOC||'('||PHONE_NUMBER||')' FROM ICOMLUSR WHERE USER_ID = PRDT.ADD_USER_ID)) AS USER_NAME_LOC, --02 POHD.PO_NO AS PO_NO, --03 MAX(POHD.PO_CREATE_DATE) AS VPO_DATE, --05 MAX(PODT.RD_DATE) AS RD_DATE, --06 MAX((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = POHD.AGENT)) AS AGENT_NAME, --07 MAX((SELECT TEL_NO FROM ICOMCMPY WHERE COM_CODE = POHD.AGENT)) AS AGENT_TEL_NO, --08 POHD.BUYER --09 FROM ICOMPOHD POHD, ICOMPODT PODT, ICOMPRDT PRDT WHERE POHD.PO_NO = #{PO_NO} AND POHD.BUYER =#{ware_house_code} AND POHD.BUYER = PODT.BUYER AND POHD.PO_NO = PODT.PO_NO AND PODT.BUYER = PRDT.BUYER AND PODT.PR_NO = PRDT.PR_NO AND PODT.PR_SEQ = PRDT.PR_SEQ GROUP BY POHD.BUYER, POHD.PO_NO

/* selectMasterWmGrStockOrderManagerPopPoSeqList*/
SELECT PO.PO_NO INV_NO, PO.PO_SEQ, PO.ITEM_QTY-NVL(PO.IV_QTY,0) INV_QTY, PO.UNIT_PRICE, '발주' AS STATUS_TEXT FROM ICOMPODT PO WHERE PO.BUYER =#{ware_house_code} AND PO.PO_NO = #{PO_NO} AND PO.PO_SEQ IN
#{PO_SEQ}
AND PO.STATUS <> 'D' AND PO.ITEM_QTY > PO.IV_QTY UNION ALL SELECT INV_NO, INV_SEQ, INV_QTY, UNIT_PRICE, DECODE(WMS_GR_QTY , INV_QTY,'입고완료','입고예정') AS STATUS_TEXT FROM ICOMIVDT IV WHERE IV.BUYER = #{ware_house_code} AND IV.PO_NO = #{PO_NO} AND IV.PO_SEQ IN
#{PO_SEQ}
AND STATUS <> 'D'

