mapper.update:
		 /* updateMasterWmGrStockOrderManagerPopICOMIVHD */

		UPDATE ICOMIVHD SET STATUS = 'D', 
                    CHANGE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD'), 
                    CHANGE_TIME = TO_CHAR(SYSDATE,'HH24MISS')  
		  WHERE BUYER  = #{BUYER}     
             AND INV_NO = #{INV_NO}   
             AND SELLER = #{SELLER}

	   		 /* updateMasterWmGrStockOrderManagerPoDelWmsIvdt */

	   UPDATE WMSIVDT SET STATUS = 'D', 
                   CHANGE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD'), 
                   CHANGE_TIME = TO_CHAR(SYSDATE,'HH24MISS')  
		WHERE BUYER = #{ware_house_code}     
  		   AND PO_NO = #{PO_NO}
           AND PO_SEQ = #{PO_SEQ}

	   	   		 /* updateMasterWmGrStockOrderManagerPoDelGrDt */

	   	   UPDATE ICOMGRDT SET STATUS = 'D', 
                    CHANGE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD'), 
                    CHANGE_TIME = TO_CHAR(SYSDATE,'HH24MISS')  
		WHERE BUYER = #{ware_house_code}     
  		   AND PO_NO = #{PO_NO}
           AND PO_SEQ = #{PO_SEQ}

	   	  /* updateMasterWmGrStockOrderManagerPoKwayOrderDetail */

     	   UPDATE TBL_ORDER_DETAIL SET	
     	   ORDER_DETAIL_STATUS   = '024007'	
     	   ,BS_CUSTOMER_PO_NO   = DECODE(NVL(BS_CUSTOMER_PO_NO,''),'','',BS_CUSTOMER_PO_NO||'_D')	
     	   ,RECORD_MODIFY_DATE       = SYSDATE	
     	   ,RECORD_MODIFY_ID         = #{USER_ID}
     	   ,RECORD_STATUS            = 'M'	
     	WHERE ORDER_DETAIL_CODE = #{ORDER_DETAIL_CODE}
     	  AND RECORD_STATUS ^= 'D'

	   /* updateMasterWmGrStockOrderManagerPoWmsStckForSTCK */

	   UPDATE WMSSTCK SET TOT_QTY = TOT_QTY - ${INV_QTY}, 
                                             AVAIL_QTY = AVAIL_QTY - (${INV_QTY}), 
                                             STC_SELLER_PRICE = ROUND(DECODE(NVL(AVAIL_QTY,0)-(${INV_QTY}),0,0,((NVL(AVAIL_QTY,0)*NVL(STC_SELLER_PRICE,0))-(${INV_QTY}*${UNIT_PRICE}))/(NVL(AVAIL_QTY,0)-(${INV_QTY}))),0) , 	
                                             CHANGE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD') 
        WHERE WAREHOUSE_CODE = #{ware_house_code}   	
          AND STDCATLG_ID = ( 
            SELECT PO.BUYER_ITEM_NO FROM ICOMPODT PO, ICOMIVDT IV  
            WHERE PO.BUYER = IV.BUYER				
        	  AND PO.PO_NO = IV.PO_NO				
        	  AND PO.PO_SEQ = IV.PO_SEQ				
              AND IV.BUYER  = #{ware_house_code}   	
              AND IV.INV_NO  = #{INV_NO}		
              AND IV.INV_SEQ = #{PO_SEQ}		
          )							
          AND AGENT = 'KRKORE0001'		
          AND CONTRACT_NO = ( 
            SELECT PO.CONTRACT_NO FROM ICOMPODT PO, ICOMIVDT IV  
            WHERE PO.BUYER = IV.BUYER				
        	  AND PO.PO_NO = IV.PO_NO				
        	  AND PO.PO_SEQ = IV.PO_SEQ				
              AND IV.BUYER  =  #{ware_house_code}   			
              AND IV.INV_NO  = #{INV_NO}		
              AND IV.INV_SEQ = #{PO_SEQ}		
          )							
          AND CONTRACT_SEQ = ( 
            SELECT PO.CONTRACT_SEQ FROM ICOMPODT PO, ICOMIVDT IV  
            WHERE PO.BUYER = IV.BUYER				
        	  AND PO.PO_NO = IV.PO_NO				
        	  AND PO.PO_SEQ = IV.PO_SEQ				
              AND IV.BUYER  =  #{ware_house_code}  		
              AND IV.INV_NO  = #{INV_NO}		
              AND IV.INV_SEQ = #{PO_SEQ}	
           )

