                                    				PO.BUYER_ITEM_NO,						
                                    				PO.CONTRACT_NO,							
                                    				PO.CONTRACT_SEQ							
                                    		  FROM ICOMPODT PO								
                                    		 WHERE PO.BUYER  =#{ware_house_code} 							
