                                    		   AND PO.PO_SEQ = #{PO_SEQ}									
                                    	  )



   	 	   	  /* deleteMasterWmGrStockOrderManagerPopAgentChange4 */	
   	 	   	                           UPDATE ICOMIVDT IV SET                                                    
		                                       CHANGE_DATE    = TO_CHAR(SYSDATE,'YYYYMMDD'),	\n");
		                                       CHANGE_TIME    = TO_CHAR(SYSDATE,'HH24MISS'),	\n");
		                                       UNIT_PRICE = ${UNIT_PRICE} ,                                                   
